using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class PlayerRhythmChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void VerifyModel(){var legacy=JsonUtility.FromJson<WorldPlayMemory>("{}");Require(legacy.Valid()&&legacy.Echo.games==0,"Historical history rejected");var m=new EchoMemory{demonstrations=1};m.Remember(new[]{0,1,1,0},new[]{.3f,.6f,.9f});Require(m.Valid()&&m.games==1,"Recorded pattern invalid");m.intervals[0]=float.NaN;Require(!m.Valid(),"Invalid timing accepted");var s=new SliceState();s.Hybrid.receipt=new ActionReceipt{action=CreatureAction.PlayWithToy,echoed=true};Require(s.Valid(),"Echo receipt invalid");s.Hybrid.receipt.rhythmGame=true;Require(!s.Valid(),"Player echo confused with villager duet");Debug.Log("BWVR_PLAYER_RHYTHM_MODEL_PASS: historical history, bounded notes/timing, typed lesson");}
 public static void Verify(Action<SliceState> completed=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var god=slice.GetComponentInChildren<CreatureHybrid>();var music=slice.GetComponentInChildren<PlayerRhythm>();var prop=music.GetComponent<CreatureAffordance>();var mind=god.GetComponent<CreatureCuriosity>();var nav=god.GetComponent<IslandNavigator>();var keys=music.GetComponentsInChildren<ChimeKey>().OrderBy(k=>k.note).ToArray();var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release objects first");var gp=god.transform.position;var gr=god.transform.rotation;var tp=music.transform.position;var tr=music.transform.rotation;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.1f,playPreference=1};field.SetValue(slice,test);god.NewSeason();foreach(var person in slice.GetComponentsInChildren<VillagerSocial>())person.ResetTask();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);
  bool Pointer(int note,bool pressed=true,bool wasPressed=false,bool tracked=true)=>(bool)typeof(QuestSlice).GetMethod("ChimePointer",Flags).Invoke(slice,new object[]{1,pressed,wasPressed,keys[note].GetComponent<Collider>(),tracked});
  void Wait(float seconds){test.Hybrid.time+=seconds;music.Advance(seconds);}
  void Record(){music.ResetWorld();foreach(int note in new[]{0,1,1,0}){Wait(note==0?.3f:.6f);Require(Pointer(note),"Key did not consume input");}}
  try{
   var lane=slice.GetComponentInChildren<BeachBall>().Bowling;Require(nav.world.Sample(lane.Start,nav.profile,5,out var start),"No observer point");god.transform.position=nav.world.ProjectFoot(start,nav.profile);god.transform.rotation=Quaternion.LookRotation(lane.Forward);nav.ResetRoute();music.transform.position=nav.world.Terrain.Project(lane.Start+lane.Forward*12*nav.world.Scale)+Vector3.up*nav.world.Scale*.25f;music.transform.rotation=Quaternion.LookRotation(lane.Forward);
   Physics.SyncTransforms();foreach(var key in keys){var ray=new Ray(key.transform.position+Vector3.up*nav.world.Scale*5,Vector3.down);Require(Physics.Raycast(ray,out var hit,nav.world.Scale*10,~0,QueryTriggerInteraction.Collide)&&hit.collider==key.GetComponent<Collider>(),"Physical ray cannot reach chime bar "+key.note);}
   Pointer(0,true,false,false);Pointer(0,true,true);Require(!music.Reserved,"Untracked/held input recorded a note");test.paused=true;Require(!music.Tap(0),"Paused note accepted");test.paused=false;slice.SetSanctuaryOpen(true);Require(!music.Tap(0),"Menu leaked a note");slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);
   god.transform.rotation=Quaternion.LookRotation(-lane.Forward);Record();Require(!music.Ready&&test.WorldPlay.Echo.demonstrations==0,"Unseen performance taught the creature");god.transform.rotation=Quaternion.LookRotation(lane.Forward);Record();Require(music.Ready&&test.WorldPlay.Echo.demonstrations==1&&test.WorldPlay.Echo.games==0,"Four witnessed notes did not create an invitation");foreach(var a in cooldowns.Keys)if(a!=prop)a.cooldown=test.Hybrid.time+200;
   bool selected=false,pauseChecked=false;for(int i=0;i<600&&test.WorldPlay.Echo.games==0;i++){god.Tick(.05f);music.Advance(.05f);selected|=mind.Current==CreatureCuriosity.Phase.EchoRhythm;if(music.Active&&music.Played==1&&!pauseChecked){test.paused=true;god.Tick(5);music.Advance(5);Require(music.Played==1&&music.Active,"Paused echo advanced");test.paused=false;pauseChecked=true;}}
   Require(selected&&pauseChecked&&test.WorldPlay.Echo.games==1&&music.PlayedNotes.SequenceEqual(new[]{0,1,1,0}),"Utility echo failed / wrong notes: "+mind.Current+" / "+god.Explanation+" played "+music.Played);var times=music.PlayedTimes;Require(Mathf.Abs(times[1]-times[0]-.6f)<.11f&&Mathf.Abs(times[2]-times[1]-.6f)<.11f&&Mathf.Abs(times[3]-times[2]-.3f)<.11f,"Echo lost demonstrated timing");Require(test.Hybrid.receipt.echoed&&!test.Hybrid.receipt.rhythmGame&&test.Hybrid.receipt.partner.Length==0&&!prop.Item.held,"Echo misattributed to villager / owned the chime");float pref=test.WorldPlay.Echo.preference;Require(god.Feedback(true)&&!god.Feedback(true)&&test.WorldPlay.Echo.preference>pref,"Echo teaching missing or repeatable");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Learned echo save invalid");completed?.Invoke(test);
   for(int i=0;i<40;i++){god.Tick(.05f);music.Advance(.05f);}Require(test.WorldPlay.Echo.games==1,"Echo completed twice");god.Interrupt("Echo cancellation QA");god.transform.position=nav.world.ProjectFoot(lane.Start,nav.profile);god.transform.rotation=Quaternion.LookRotation(lane.Forward);nav.ResetRoute();Record();Require(mind.TryBeginEcho(prop),"Second invitation not claimable");prop.Item.held=true;music.Advance(.05f);god.Tick(.05f);Require(!music.Active&&!music.Claimed&&test.WorldPlay.Echo.games==1&&!test.Hybrid.receipt.eligible,"Pickup credited incomplete echo");prop.Item.held=false;
   Debug.Log("BWVR_PLAYER_RHYTHM_PLAY_PASS: physical keys and edge/tracking/menu/pause protection; unseen rejection; four witnessed notes; utility-selected echo in exact order/timing; exclusive carry, pause, one-shot feedback/save, duplicate and pickup cancellation guards");
  }finally{prop.Item.held=false;prop.Item.GetComponent<Collider>().enabled=true;god.Interrupt("Echo QA complete");music.ResetWorld();field.SetValue(slice,original);god.NewSeason();foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;god.transform.SetPositionAndRotation(gp,gr);nav.ResetRoute();music.transform.SetPositionAndRotation(tp,tr);slice.SetSanctuaryOpen(false);}
 }
}
}
